class Solution {
public:
    bool confusingNumber(int n) {
        vector<int> map(10, -1);
        map[0] = 0; map[1] = 1; map[6] = 9; map[8] = 8; map[9] = 6;
        long long orig = n, rotated = 0, temp = n;
        while (temp > 0) {
            int digit = temp % 10;
            if (map[digit] == -1) return false;
            rotated = rotated * 10 + map[digit];
            temp /= 10;
        }
        return rotated != orig;
    }
};

class Solution {
    public boolean confusingNumber(int n) {
        int[] map = new int[] {0, 1, -1, -1, -1, -1, 9, -1, 8, 6};
        long orig = n, rotated = 0, temp = n;
        while (temp > 0) {
            int digit = (int) (temp % 10);
            if (map[digit] == -1) return false;
            rotated = rotated * 10 + map[digit];
            temp /= 10;
        }
        return rotated != orig;
    }
}

var confusingNumber = function(n) {
    const map = { 0: 0, 1: 1, 6: 9, 8: 8, 9: 6 };
    let orig = n;
    let rotated = 0;
    while (n > 0) {
        const digit = n % 10;
        if (map[digit] === undefined) return false;
        rotated = rotated * 10 + map[digit];
        n = Math.floor(n / 10);
    }
    return rotated !== orig;
};
